 public sealed class MediaClock {readonly Stopwatch watch=Stopwatch.StartNew();readonly object sync=new object();TimeSpan excluded=TimeSpan.Zero,pauseAt;bool paused,ended;TimeSpan end;public bool Paused{get{lock(sync)return paused;}}public double Seconds{get{lock(sync)return ended?end.TotalSeconds:((paused?pauseAt:watch.Elapsed)-excluded).TotalSeconds;}}public void Pause(){lock(sync){if(paused||ended)return;pauseAt=watch.Elapsed;paused=true;}}public void Resume(){lock(sync){if(!paused||ended)return;excluded+=watch.Elapsed-pauseAt;paused=false;}}public void Finish(){lock(sync){if(ended)return;end=(paused?pauseAt:watch.Elapsed)-excluded;ended=true;}}}
 public static class Args {public static string Q(string value){var b=new StringBuilder("\"");int n=0;foreach(char c in value??""){if(c=='\\'){n++;continue;}if(c=='"'){b.Append('\\',n*2+1);b.Append('"');n=0;}else{b.Append('\\',n);n=0;b.Append(c);}}b.Append('\\',n*2);b.Append('"');return b.ToString();}}
