  sealed class Lease:IDisposable {public Bitmap Image;public readonly object DrawLock=new object();int refs=1;readonly CameraFeed owner;public Lease(Bitmap image,CameraFeed feed){Image=image;owner=feed;}public void Retain(){Interlocked.Increment(ref refs);}public void Dispose(){if(Interlocked.Decrement(ref refs)==0)owner.Return(Image);}}
  readonly object sync=new object(),poolSync=new object();readonly Stack<Bitmap> pool=new Stack<Bitmap>();Lease latest;Process process;Thread reader,tracker;readonly ManualResetEvent first=new ManualResetEvent(false);volatile bool closing,ended;bool poolClosed;DateTime lastFrame;string error="";OpenCvSharp.CascadeClassifier faces;PointF center=new PointF(.5f,.5f);public volatile bool Tracking;public bool TrackingAvailable{get;private set;}long received;Stopwatch running=new Stopwatch();public long FramesReceived{get{lock(sync)return received;}}public double ReceivedFps{get{lock(sync)return received/Math.Max(.001,running.Elapsed.TotalSeconds);}}public double FrameAgeMs{get{lock(sync)return latest==null?double.PositiveInfinity:(DateTime.UtcNow-lastFrame).TotalMilliseconds;}}
