  public static string CaptureArguments(string device,bool synthetic,int rate,string profile=null){
   bool virtualCamera=!synthetic&&(device??"").IndexOf("Broadcast",StringComparison.OrdinalIgnoreCase)>=0;
   string negotiation="";
   if(!synthetic){if(profile=="1080p / 30")negotiation=" -video_size 1920x1080 -framerate 30";else if(profile=="720p / 30"||virtualCamera&&profile!="Dispositivo padrão")negotiation=" -video_size 1280x720 -framerate 30";}
   string input=synthetic?"-re -f lavfi -i testsrc2=size=640x480:rate="+Math.Max(1,Math.Min(120,rate)):"-thread_queue_size 1 -f dshow -rtbufsize 16M"+negotiation+" -i "+Args.Q("video="+device);
   return "-hide_banner -loglevel warning -nostdin -filter_threads 1 "+input+" -an -vf scale=640:480:force_original_aspect_ratio=decrease,pad=640:480:(ow-iw)/2:(oh-ih)/2 -fps_mode passthrough -threads 1 -pix_fmt bgr24 -f rawvideo pipe:1";
  }
  public void Start(string ff,string device,bool synthetic=false,int syntheticFps=30,string profile=null){if(process!=null)throw new InvalidOperationException("Câmera já aberta.");var psi=new ProcessStartInfo(ff,CaptureArguments(device,synthetic,syntheticFps,profile)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};try{string model=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"haarcascade_frontalface_default.xml");if(File.Exists(model)){faces=new OpenCvSharp.CascadeClassifier(model);TrackingAvailable=!faces.Empty();}}catch{TrackingAvailable=false;}
   process=new Process{StartInfo=psi};process.ErrorDataReceived+=delegate(object sender,DataReceivedEventArgs e){if(e.Data!=null)lock(sync){error=e.Data.Length>500?e.Data.Substring(0,500):e.Data;}};process.Start();process.BeginErrorReadLine();try{process.PriorityClass=ProcessPriorityClass.BelowNormal;}catch{}running.Start();reader=new Thread(Read){IsBackground=true};reader.Start();tracker=new Thread(TrackLoop){IsBackground=true};tracker.Start();if(!first.WaitOne(10000)||!IsReady){string message=Error;Dispose();throw new InvalidOperationException("A câmera não forneceu imagem. Pode estar em uso, desconectada ou bloqueada nas permissões do Windows. "+message);}}
  Bitmap Borrow(){lock(poolSync){if(pool.Count>0)return pool.Pop();}return new Bitmap(640,480,PixelFormat.Format24bppRgb);}
  void Return(Bitmap image){lock(poolSync){if(!poolClosed&&pool.Count<5){pool.Push(image);return;}}image.Dispose();}
  Lease Acquire(){lock(sync){var frame=latest;if(frame!=null)frame.Retain();return frame;}}
  void Read(){try{byte[] data=new byte[640*480*3];while(!closing){int count=0;while(count<data.Length&&!closing){int n=process.StandardOutput.BaseStream.Read(data,count,data.Length-count);if(n==0)return;count+=n;}if(closing)return;Bitmap image=Borrow();try{var bits=image.LockBits(new Rectangle(0,0,640,480),ImageLockMode.WriteOnly,PixelFormat.Format24bppRgb);try{Marshal.Copy(data,0,bits.Scan0,data.Length);}finally{image.UnlockBits(bits);}}catch{Return(image);throw;}Lease old;lock(sync){old=latest;latest=new Lease(image,this);lastFrame=DateTime.UtcNow;received++;}if(old!=null)old.Dispose();first.Set();}}catch(Exception ex){lock(sync)error=ex.Message;}finally{ended=true;first.Set();}}
  void TrackLoop(){try{using(var color=new OpenCvSharp.Mat(480,640,OpenCvSharp.MatType.CV_8UC3))using(var small=new OpenCvSharp.Mat())using(var gray=new OpenCvSharp.Mat()){while(!closing){if(!Tracking||!TrackingAvailable){Thread.Sleep(80);continue;}var watch=Stopwatch.StartNew();using(var frame=Acquire()){if(frame!=null){lock(frame.DrawLock){var bits=frame.Image.LockBits(new Rectangle(0,0,640,480),ImageLockMode.ReadOnly,PixelFormat.Format24bppRgb);try{for(int row=0;row<480;row++)NativeCopy(IntPtr.Add(color.Data,row*640*3),IntPtr.Add(bits.Scan0,row*bits.Stride),(UIntPtr)(640*3));}finally{frame.Image.UnlockBits(bits);}}OpenCvSharp.Cv2.Resize(color,small,new OpenCvSharp.Size(320,240));OpenCvSharp.Cv2.CvtColor(small,gray,OpenCvSharp.ColorConversionCodes.BGR2GRAY);var found=faces.DetectMultiScale(gray,1.15,4,OpenCvSharp.HaarDetectionTypes.ScaleImage,new OpenCvSharp.Size(25,25));if(found.Length>0){var best=found[0];foreach(var f in found)if(f.Width*f.Height>best.Width*best.Height)best=f;lock(sync){center=new PointF(center.X*.7f+(best.X+best.Width/2f)/320*.3f,center.Y*.7f+(best.Y+best.Height/2f)/240*.3f);}}}}int delay=Math.Max(1,200-(int)watch.ElapsedMilliseconds);Thread.Sleep(delay);}}}catch{TrackingAvailable=false;}}
