  public Bitmap Frame(){using(var frame=Acquire()){if(frame==null)return null;lock(frame.DrawLock)return (Bitmap)frame.Image.Clone();}}
  public bool DrawLatest(Graphics g,Rectangle box,string shape,float zoom,bool mirror,bool tracking){using(var frame=Acquire()){if(frame==null)return false;lock(frame.DrawLock)CameraDraw.Draw(g,frame.Image,box,shape,zoom,mirror,tracking?FaceCenter:new PointF(.5f,.5f));return true;}}
