 } public static class CameraDraw {
  public static void Draw(Graphics g,Bitmap image,Rectangle box,string shape,float zoom,bool mirror,PointF center){if(image==null||box.Width<2||box.Height<2)return;zoom=Math.Max(1,Math.Min(4,zoom));float ratio=(float)box.Width/box.Height;float w=Math.Min(image.Width,image.Height*ratio)/zoom,h=w/ratio;float x=Math.Max(0,Math.Min(image.Width-w,center.X*image.Width-w/2)),y=Math.Max(0,Math.Min(image.Height-h,center.Y*image.Height-h/2));var state=g.Save();try{using(var clip=new GraphicsPath()){if(shape=="Redonda")clip.AddEllipse(box);else clip.AddRectangle(box);g.SetClip(clip,CombineMode.Intersect);g.InterpolationMode=InterpolationMode.HighQualityBilinear;Point[] points=mirror?new[]{new Point(box.Right,box.Top),new Point(box.Left,box.Top),new Point(box.Right,box.Bottom)}:new[]{box.Location,new Point(box.Right,box.Top),new Point(box.Left,box.Bottom)};g.DrawImage(image,points,Rectangle.Round(new RectangleF(x,y,w,h)),GraphicsUnit.Pixel);}}finally{g.Restore(state);}}
 }
 public class AudioDeviceChoice {public string Id,Name;public override string ToString(){return Name;}}
 public static class AudioDevices {
  public static List<AudioDeviceChoice> List(bool output){var result=new List<AudioDeviceChoice>{new AudioDeviceChoice{Id="",Name="Padrão do Windows"}};using(var e=new MMDeviceEnumerator()){var devices=e.EnumerateAudioEndPoints(output?DataFlow.Render:DataFlow.Capture,DeviceState.Active);foreach(var d in devices){result.Add(new AudioDeviceChoice{Id=d.ID,Name=d.FriendlyName});d.Dispose();}}return result;}
 }
 public sealed class AudioSession:IDisposable {
  sealed class Track {public WasapiCapture Capture;public MMDevice Device;public WaveFileWriter Writer;public string File;public ManualResetEvent Stopped=new ManualResetEvent(false);public object Sync=new object();public string Error;}
  readonly List<Track> tracks=new List<Track>();readonly MediaClock clock;public AudioSession(MediaClock time){clock=time;}
  public void Start(string prefix,bool system,bool mic,string outputId,string inputId){try{if(system)Add(prefix+"-system.wav",true,outputId);if(mic)Add(prefix+"-mic.wav",false,inputId);}catch{Dispose();throw;}}
  void Add(string file,bool output,string id){var t=new Track{File=file};using(var e=new MMDeviceEnumerator())t.Device=string.IsNullOrEmpty(id)?e.GetDefaultAudioEndpoint(output?DataFlow.Render:DataFlow.Capture,Role.Multimedia):e.GetDevice(id);t.Capture=output?(WasapiCapture)new WasapiLoopbackCapture(t.Device):new WasapiCapture(t.Device);t.Writer=new WaveFileWriter(file,t.Capture.WaveFormat);t.Capture.DataAvailable+=delegate(object sender,WaveInEventArgs e){if(clock.Paused)return;lock(t.Sync){if(t.Writer==null)return;try{long expected=(long)(Math.Max(0,clock.Seconds-(double)e.BytesRecorded/t.Writer.WaveFormat.AverageBytesPerSecond)*t.Writer.WaveFormat.AverageBytesPerSecond);expected-=expected%t.Writer.WaveFormat.BlockAlign;Pad(t,expected);t.Writer.Write(e.Buffer,0,e.BytesRecorded);}catch(Exception ex){t.Error=ex.Message;}}};t.Capture.RecordingStopped+=delegate(object sender,StoppedEventArgs e){if(e.Exception!=null)t.Error=e.Exception.Message;try{t.Stopped.Set();}catch(ObjectDisposedException){}};tracks.Add(t);t.Capture.StartRecording();}
  static void Pad(Track t,long target){byte[] silence=new byte[16384];while(t.Writer.Length<target){int n=(int)Math.Min(silence.Length,target-t.Writer.Length);t.Writer.Write(silence,0,n);}}
  public void CheckHealth(){foreach(var t in tracks)if(t.Error!=null)throw new InvalidOperationException("O dispositivo de áudio foi interrompido: "+t.Error);}
  public string[] Stop(){var files=new List<string>();foreach(var t in tracks){t.Capture.StopRecording();if(!t.Stopped.WaitOne(5000))throw new Exception("O dispositivo de áudio não respondeu ao parar.");lock(t.Sync){if(t.Error!=null)throw new Exception("Captura de áudio falhou: "+t.Error);long bytes=(long)(clock.Seconds*t.Writer.WaveFormat.AverageBytesPerSecond);bytes-=bytes%t.Writer.WaveFormat.BlockAlign;Pad(t,Math.Max(bytes,t.Writer.WaveFormat.BlockAlign));t.Writer.Dispose();t.Writer=null;}files.Add(t.File);}return files.ToArray();}
  public void Dispose(){foreach(var t in tracks){try{t.Capture.StopRecording();t.Stopped.WaitOne(1500);}catch{}t.Capture.Dispose();lock(t.Sync){if(t.Writer!=null){t.Writer.Dispose();t.Writer=null;}}t.Device.Dispose();t.Stopped.Dispose();}tracks.Clear();}
 }
